## 3 Recomendaciones Concretas

### 1. Extraer patrón "target + dependencias" a función reutilizable

**En vez de** (líneas 155-195, 230-270, 280-320 — 3 implementaciones casi idénticas):

```python
def _compress_refactor(top_capsules, all_capsules):
    target = top_capsules[0] if top_capsules else None
    if not target:
        return ""
    nodes = [build_node(target, ["signature", "file_path", "docstring", "parametros"])]
    all_by_name = {c.name: c for c in all_capsules}
    for call in target.calls:
        if call in all_by_name:
            nodes.append(build_node(all_by_name[call], ["signature", "file_path", "docstring"]))
    for c in all_capsules:
        if target.name in c.calls:
            nodes.append(build_node(c, ["signature", "file_path", "docstring"]))
    return serialize_context(nodes)
```

**Usar**:

```python
def _build_target_graph(target: Capsule, all_capsules: list[Capsule],
                        depth: int = 1, include_body: bool = False) -> list[dict]:
    """Construye grafo target + callers + callees hasta depth."""
    if not target:
        return []
    all_by_name = {c.name: c for c in all_capsules}
    nodes = [build_node(target, _props_for_depth(depth, include_body))]
    visited = {target.name}

    # Callees BFS
    queue = [(target, 0)]
    while queue:
        current, d = queue.pop(0)
        if d >= depth:
            continue
        for call in current.calls:
            if call in all_by_name and call not in visited:
                c = all_by_name[call]
                nodes.append(build_node(c, _props_for_depth(d + 1, include_body)))
                visited.add(call)
                queue.append((c, d + 1))

    # Callers (solo depth 1)
    for c in all_capsules:
        if target.name in c.calls and c.name not in visited:
            nodes.append(build_node(c, ["signature", "file_path", "docstring"]))
            visited.add(c.name)

    return nodes

# Uso:
# _compress_refactor -> _build_target_graph(target, all_capsules, depth=1)
# _compress_debug    -> _build_target_graph(target, all_capsules, depth=2, include_body=True)
```

### 2. Estrategia de compresión como objetos polimórficos (Strategy Pattern)

**En vez de** (líneas 55-90 — `compress()` con 12 elif):

```python
def compress(...):
    if task_type == "code_gen":
        result = _compress_query(top_capsules, budget_tokens)
    elif task_type == "code_edit":
        result = _compress_code_edit(top_capsules)
    elif task_type == "search":
        result = _compress_search(...)
    # ... 9 elif más
```

**Usar**:

```python
from abc import ABC, abstractmethod
from dataclasses import dataclass

class CompressionStrategy(ABC):
    @abstractmethod
    def compress(self, top: list[Capsule], all_: list[Capsule],
                 budget: int, **kwargs) -> str: ...

@dataclass
class CodeGenStrategy(CompressionStrategy):
    def compress(self, top, all_, budget, **kw) -> str:
        return _compress_code_gen(all_)  # lógica actual extraída

@dataclass
class DebugStrategy(CompressionStrategy):
    def compress(self, top, all_, budget, **kw) -> str:
        return _compress_debug(top, all_)  # lógica actual

STRATEGIES: dict[str, CompressionStrategy] = {
    "code_gen": CodeGenStrategy(),
    "debug": DebugStrategy(),
    "search": SearchStrategy(),
    # ... registro explícito, no reflexión
}

def compress(...):
    strategy = STRATEGIES.get(task_type, QueryStrategy())
    result = strategy.compress(top_capsules, all_capsules, budget_tokens,
                                dir_filter=dir_filter, query=query)
    # post-procesamiento común (framework, paths)
    ...
```

